def topo_sort(graph):
    st={}; out=[]
    def go(n):
        c=st.get(n,0)
        if c==1: return False
        if c==2: return True
        st[n]=1
        for d in graph.get(n,[]):
            if not go(d): return False
        st[n]=2; out.append(n); return True
    for n in graph:
        if not go(n): return None
    return out

